-- Pieces, part 3 of 3 (Open Opus / Wikidata, CC0). Run after the composers seed.
-- The titles are packed as base64 JSON so the SQL editor has nothing to
-- misread (some titles contain quotes, semicolons and colons). Safe to re-run.
insert into public.pieces (composer_id, title)
select c.id, v.t
from json_to_recordset(convert_from(decode('', 'base64'), 'UTF8')::json) as v(c text, t text)
join public.composers c on c.name = v.c
on conflict (composer_id, title) do nothing;
